quests[32324] = { id = 32324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Signal", description = "The soulstone shards fuse together easily in your hands.\n\nStrangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.", sourceObjective = "Follow the soulstone to the gates of the Black Temple.", sourceObjectiveStatus = "unverified-source-field" }
quests[32325] = { id = 32325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Black Temple", description = "It's clear that Jubeka's soulstone has lead you here to the Black Temple. \n\nThe question remains... why?\n\nThe only remaining option is to head inside and figure out why they were here.", sourceObjective = "Look for Jubeka's mark on the main entrance of the Black Temple. Once inside, speak to Jubeka at the Temple Summit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32326] = { id = 32326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insertion", description = "{name}! You'll do perfectly.\n\nWe know where the Alliance have hidden the Divine Bell. We've already inserted an agent into enemy territory, we just need you to help him execute his mission.\n\nPack up, {name}. You're headed to Darnassus.", sourceObjective = "Use the Sunreaver Portal in Domination Point to secure a teleport to Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32327] = { id = 32327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darnassus Mission", description = "The Divine Bell is in the city. We don't want to cause a scene, we just want the artifact. I need you to find a way in, WITHOUT getting caught. That means no mounts, no flying, no fighting.\n\nI can provide aid. I will magically cloak you, so you may move with stealth. I will also give you a small charm that you may use to return to safety, should you get in trouble.\n\nNow go, {name}. Go, locate the bell, and tag it to be teleported back with you.", sourceObjective = "Locate the Divine Bell.\n\nYou may use the Silvermoon Charm to return to Fanlyr if you get in trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[32328] = { id = 32328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victorious Return", description = "The portal by my side will return you safely to Domination Point. I will return behind you; I must clean up our tracks a bit before we leave, so that Proudmoore doesn't discover our involvement.", sourceObjective = "Report your success to Nazgrim at Domination Point in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32329] = { id = 32329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get My Results!", sourceObjective = "Speak with Lor'themar Theron in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[32330] = { id = 32330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in the Box?", description = "We are trying to uncover the secrets of one of the mogu artifacts Garrosh insisted we investigate. It is proving most difficult, as anyone who probes it magically is greatly affected by raw, negative emotions.\n\nI called in the assistance of Arch-mage Aethas of the Sunreavers in the hopes that he and Rommath could crack this puzzle. They asked for you specifically - apparently you have some relevant experience?\n\nGo to the chamber below Farstrider Square east of here and see if you can assist them.", sourceObjective = "Assist with Aethas and Rommath's experiment.", sourceObjectiveStatus = "unverified-source-field" }
quests[32331] = { id = 32331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirin Tor", sourceObjective = "Use the Portal to the Purple Parlor in Lion's Landing and meet with Anduin Wrynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[32332] = { id = 32332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Riddle: Mercy", description = "So, you wake up the Monkey King for a mallet hmmm? Answer first, these riddles three, and then the mallet you shall see.\n\nFirst riddle!\n\n  \"Softly singing a song of pain\n\n    There is a creature tortured and lame.\n\n    Way down south and beyond the wall,\n\n    It hides from its wikket masters' call.\n\n    Seek out the creature sad and somber,\n\n    And free it from its untamed amber.\"\n\nBring me the untamed amber.", sourceObjective = "Find the object the Monkey King described in his riddle.", sourceObjectiveStatus = "unverified-source-field" }
quests[32333] = { id = 32333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Riddle: Fellowship", description = "You want to stop the Divine Bell? We need the mallet first.\n\nYou want the mallet? We need to be friends first.\n\nYou want to be friends? We need a Metal brew first. \n\nYou want a Metal brew? You need to go to the Shrine of Fellowship first. \n\nYou want to go to the Shrine of Fellowship? Great! It's in the Jade Forest southeast of the Tian Monastery.\n\nRing the bell and get the Monkey King some brew while there. Oh... you may have to fight for it.", sourceObjective = "Obtain Metal Brew.", sourceObjectiveStatus = "unverified-source-field" }
quests[32334] = { id = 32334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Riddle: Strength", description = "The mallet you seek is not a toy for children,\n\nIt calls trouble like the song of a siren.\n\nA test of strength the Monkey King will require,\n\nBefore you receive this tool of your desire.\n\nAt the Temple of the White Tiger you will find\n\nA challenger to test how well you are resigned\n\nStep through the main door and then turn right down the ramp\n\nChallenge the ook waiting for you there like a champ!", sourceObjective = "Defeat the Challenger at the Tiger Temple.", sourceObjectiveStatus = "unverified-source-field" }
quests[32335] = { id = 32335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Prank", description = "So riddles three you answered me. Good good. The Monkey King is not so old that he tells just anyone his tricks.\n\nIt was the greatest prank ever!\n\nYou want to hear story of the Mallet and the Monkey? Too bad! No choice!", sourceObjective = "Listen to the Monkey King's story.", sourceObjectiveStatus = "unverified-source-field" }
quests[32336] = { id = 32336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Handle", sourceObjective = "Recover the Mallet Handle.", sourceObjectiveStatus = "unverified-source-field" }
quests[32337] = { id = 32337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Head", description = "Monkey King receive word on where to find the head,\n\nThe hozen who got it has long since been dead. \n\nKunzen chiefs pass the relic from father to son, \n\nBut then virmen Skiggit came and the head it won. \n\nNow the wikket worships it in a hollow. \n\nSince it was too ookin' big for him to swallow. \n\nI sent a royal finder north to find him and stand. \n\nLook for finder in mountains west of the Heartland.", sourceObjective = "Recover the Mallet Head.", sourceObjectiveStatus = "unverified-source-field" }
quests[32338] = { id = 32338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harmonic Ointment", description = "Legends are not born, they are made.\n\nMuch like your next target, a mogu named \"The Blade.\" \n\nIn his bags you will find,\n\nAn ointment whose sound plays with the mind.\n\nBring this nibby ointment to the Monkey King!\n\nAnd with it, he shall make the mallet sing!\n\nTravel north along the wall, and when you reach the end, turn left.", sourceObjective = "Recover the Harmonic Ointment.", sourceObjectiveStatus = "unverified-source-field" }
quests[32340] = { id = 32340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder the Black Temple", description = "While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...You will learn:", sourceObjective = "Loot everything you can grab and reach the end of the Den of Mortal Delights.", sourceObjectiveStatus = "unverified-source-field" }
quests[32342] = { id = 32342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit Trap", description = "Within the ruins we have identified several powerful mogu artifacts. They trapped spirits within, probably to use them in some ritual or conjuration.\n\nThey are a type of device that we haven't identified and desperately need to study - they may reveal more of the secrets of the mogu's spirit binding techniques. \n\nGo, find us a few samples so that we may continue a proper study.", sourceObjective = "Collect 3 Spirit Traps.", sourceObjectiveStatus = "unverified-source-field" }
quests[32343] = { id = 32343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudei's Lieutenants", description = "There are two extremely powerful mogu spirits that the Alliance unearthed in their ineptitude.\n\nThese are choice targets for us, {class}. If you kill them and collect each of their essences, we could make great progress on decoding the history of this strange ruin.", sourceObjective = "Collect Meng-do's Essence and Gen-li's Essence in the Ruins of Ogudei.", sourceObjectiveStatus = "unverified-source-field" }
quests[32344] = { id = 32344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Is A Mystery", description = "We have detected several... anomalies in these mines, of an arcane or spiritual nature. They are disrupting our attempts to discern the nature of the magic used in the spirit binding rituals here.\n\nThey are quite elusive, but we've managed to isolate the arcane signature of one of these anomalies, and one of our mages has enchanted this bauble with its signature.\n\nTake the bauble. It will begin to glow more brightly as you approach the anomaly. Once you reach it, you can use the bauble to draw it out.", sourceObjective = "Use the Arcane Bauble to find an anomaly within the Ruins of Ogudei.", sourceObjectiveStatus = "unverified-source-field" }
quests[32345] = { id = 32345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Not Monsters!", description = "The Reliquary may have had a bad name in the past, but we're not monsters. We simply hold different views about archaeology than the Explorer's League.\n\nWe do focus on performing acts of heroism from time to time. So go, liberate some of the pandaren slave spirits in the ruins.", sourceObjective = "Liberate 14 Troubled Slave Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[32346] = { id = 32346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oi Ain't Afraid o' No Ghosts!", description = "Look. We got a nasty problem here, and ol' Troteman back at Lion's Landing's gonna throw us out of here if we don't get things under control.\n\nGive us a hand, please!", sourceObjective = "Kill 12 Spiritbound Mogu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32347] = { id = 32347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviction Notice", description = "The bloody Reliquary's snuck into the ruins. They've taken the lower section and are conducting all kinds of magical shenanigans down there.\n\nIt's time we gave 'em an eviction notice, in the form of your boot in their rear!", sourceObjective = "Kill any 10 members of the Reliquary in the Ruins of Ogudei.", sourceObjectiveStatus = "unverified-source-field" }
quests[32348] = { id = 32348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick 'em While They're Down", description = "The Alliance may think they have a stranglehold on the ruins, given that their base of operations is close.\n\nWe're going to disabuse them of that notion. Go take out some of their guards.", sourceObjective = "Kill 12 Lion's Landing military units.", sourceObjectiveStatus = "unverified-source-field" }
quests[32351] = { id = 32351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Thunder", description = "Ah, {name}, we meet again. I have heard some wondrous news.\n\nHigh Chieftain Baine Bloodhoof of the tauren has arrived here on Pandaria.\n\nHe meets with Warchief Garrosh Hellscream and Regent Lord Lor'themar Theron now, at the Shrine of Two Moons in the Vale of Eternal Blossoms.\n\nHe sent me a strange request - to send him a loyal champion of the Horde, capable of combat... and discretion.\n\nI can think of none better to send than you. Speak to Tak-Tak if you seek transport.", sourceObjective = "Find High Chieftain Baine Bloodhoof at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32352] = { id = 32352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering Storm", description = "If General Nazgrim sent you, then I trust you are capable of discretion.\n\nWhen I arrived here, I found Garrosh... experimenting... with some ancient power that he found in the mountains to the north.\n\nHe believes that this \"sha\" can strengthen our soldiers.\n\nUnfortunately, so far the results have been quite the opposite.\n\nOur troops are erupting into random violence. Go and interrogate them. If they threaten you, be prepared to defend yourself.", sourceObjective = "Confront 6 Sha-Touched Grunts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32355] = { id = 32355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harmonic Mallet", sourceObjective = "Find Anduin at the Tomb of Conquerors. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32358] = { id = 32358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulcore" }
quests[32362] = { id = 32362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Dalaran", description = "Jaina is refusing to hear me out. Father was hoping I would have some pull with her, but I think she still sees me as a child.\n\nYou, on the other hand, are a hero of the Alliance and I know she respects your deeds.\n\nIs there something you can say to her to convince her we need her help?", sourceObjective = "Speak with Jaina Proudmoore and hear her story.", sourceObjectiveStatus = "unverified-source-field" }
quests[32363] = { id = 32363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kun-Lai Expedition", description = "I have another message for you from High Chieftain Bloodhoof.\n\nIt seems you've made quite the impression on him.\n\nHe travels with the Warchief's vanguard into Kun-Lai Summit, to the north. They have set up an outpost, Garrosh'ar Advance, just east of One Keg.\n\nYou had best not keep him waiting. Speak to Tak-Tak for swift travel.", sourceObjective = "Find Baine Bloodhoof at Garrosh'ar Advance. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32368] = { id = 32368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Wine", description = "The tincture is ready. Now, drink.", sourceObjective = "Drink the Memory Wine and witness Shan Kien's Past.", sourceObjectiveStatus = "unverified-source-field" }
quests[32369] = { id = 32369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Past" }
quests[32370] = { id = 32370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kun-Lai Expedition", description = "Glory to the Alliance, {class}. We are making gains against the Horde in the Krasarang Wilds, albeit slowly.\n\nWhile we hold the front here, we need your help to fight a different battle - one that strikes at our enemy's heart.\n\nOur SI:7 informant, Agent Connelly, has sent word that a Horde vanguard is moving up into the northern reaches of Kun-Lai Summit.\n\nGo without delay. Make contact with Agent Connelly in the field, and find out what is going on.\n\nSpeak to Fennie over there for a flight in.", sourceObjective = "Find Connelly at the Grummle Bazaar. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32371] = { id = 32371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Wine", description = "<The radio static crackles, and Agent Connelly continues speaking.>\n\nNow comes the real challenge, <laddie/lassie>. \n\nHead on over to the center of camp and see what you can overhear.", sourceObjective = "Use the Kor'kron Disguise to enter the camp. Then drink the Memory Brew and witness Shan Kien's past.", sourceObjectiveStatus = "unverified-source-field" }
quests[32372] = { id = 32372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Subjugation", description = "The Kor'kron have been trained to be the finest, most loyal soldiers of the Warchief. Their presence here means that Garrosh fears an uprising.\n\nVol'jin and his people are as much a part of the Horde as any orc.\n\nWe must break this occupation and free the trolls. It pains me to say this, but you must eliminate enough of the Kor'kron so that the trolls can retake their city. Then meet me at Darkspear Hold so we might challenge their officer directly.", sourceObjective = "Defeat 10 Kor'kron Overseers, 5 Kor'kron Subjugators, and Gul'tar the Subjugator.", sourceObjectiveStatus = "unverified-source-field" }
quests[32373] = { id = 32373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. The Alliance has landed on the shores with the full might of its navy. Your King aims to check Horde aggression in this new land.\n\nGarrosh Hellscream is propelling the Horde headfirst into battle, but King Varian Wrynn is a little more of a mystery to me. Do you have a moment? I'd like to talk to you about this leader of yours.", sourceObjective = "Speak with Wrathion at the Tavern in the Mists.", progress = "I love a good chat.", completion = "I am curious to see how King Wrynn rises to the occasion.\n\nI am even more curious to see what YOU are capable of. Let's find out...", sourceObjectiveStatus = "unverified-source-field" }
quests[32374] = { id = 32374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Alliance deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", sourceObjective = "Kill Horde forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Horde has learned that their actions in Pandaria will not be unopposed.\n\nI believe it is time for a more substantial challenge...", sourceObjectiveStatus = "unverified-source-field" }
quests[32375] = { id = 32375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dash of That", description = "100 Buttonbelly Mushrooms. Must be freshly harvested from a wet, dark place.\n\n<Scrawled along the edge of the page is a hand-written note.>\n\nFungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)", sourceObjective = "Collect 100 Buttonbelly Mushrooms.", sourceObjectiveStatus = "unverified-source-field" }
quests[32376] = { id = 32376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Valley!", description = "This sealed communication was sent for you, along with urgent orders to travel to the Valley of Emperors in Kun-Lai Summit.\n\nThis looks serious. I'd not delay if I were you.\n\nSpeak to Tak-Tak for transportation.", sourceObjective = "Find your \"Friend from Silvermoon\" at the Valley of Emperors. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32377] = { id = 32377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Kor'kron In Our Midst", description = "Garrosh is hell-bent on finding that Divine Bell. I wouldn't be surprised if he tore Kun-Lai Summit apart to find that artifact.\n\nThe Warchief's called a gathering at Garrosh'ar Advance, just to our north.\n\nI need to stay here to monitor troop movements, so you'll have to infiltrate their camp and overhear their discussion.\n\nGo to Garrosh'ar Advance and steal some Kor'kron Armor from Reavers, Honor Guards, and Scouts.\n\nTake this radio earpiece. Don't contact me... I'll contact you.", sourceObjective = "Collect 1 Kor'kron Helmet, 1 Kor'kron Armor, and 1 Kor'kron Boots, then combine them into a Kor'kron Disguise.", sourceObjectiveStatus = "unverified-source-field" }
quests[32378] = { id = 32378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing a Path", description = "First thing's first. If we're going to take the leader captive, we'll need to thin the numbers of his agents.\n\nBe careful. These mogu are particularly dangerous - they appear to be manipulating the sha in ways we haven't seen before.", sourceObjective = "Kill 10 Korune Mogu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32379] = { id = 32379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Korune", description = "I'm not prepared to throw away more of our people fighting against an enemy we don't know or understand. \n\nSee if you can find any clues in the area as to who exactly these \"Korune\" mogu are. A contingency in case this operation doesn't go as planned.", sourceObjective = "Find the document Legacy of the Korune in the Valley of the Emperors, and collect the Sealed Korune Artifact and Korune Orders from Korune Mogu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32380] = { id = 32380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Around", description = "We're going to need help if we hope to figure out Garrosh's plans for Pandaria.\n\nI have someone specific in mind, but he will not be easy to convince.\n\nAgent Connelly considers himself retired, but one does not simply leave the SI: 7. We've had an undercover agent following his every move for months.\n\nCurrently, he is disguising himself as a high roller at Bizmo's Brawlpub. Something about settling an old debt.\n\nMeet with our undercover agent in the Brawler's Guild.", sourceObjective = "Report to undercover agent Townsley in Bizmo's Brawlpub in the Stormwind side of Deeprun Tram.", progress = "So you think you are going to talk Connelly out of retirement? Good luck!", completion = "Following Connelly has been interesting to say the least. The man is a master of disguise!\n\nTalking him into joining you won't be the hard part, {class}. Figuring out which of these lively individuals is him will be next to impossible.", sourceObjectiveStatus = "unverified-source-field" }
quests[32381] = { id = 32381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch A Spy", description = "Now, I could tell you who Connelly is, but that would be too easy! To catch a spy you have to think like a spy.\n\nYou have to pass the test first!\n\nThe small things can say a lot about a person. It's all in the details.\n\nI'm going to give you a drink to deliver. I will give you a small detail about something the recipient is wearing. From there it will be up to you.\n\nBe careful who you pick to give drinks to. People here tend to get pretty hostile if you give them the wrong order!", sourceObjective = "Deliver the Pink Marmot, the Mogu Melon Twist, and the Rusty Dagger to the correct patron.", progress = "You learn to look at the details when you barkeep.", completion = "You have a keen eye, {class}! I think you are ready to meet Connelly.", sourceObjectiveStatus = "unverified-source-field" }
quests[32382] = { id = 32382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's In Deep", description = "Agent Connelly has managed to infiltrate Garrosh's camp in Kun-Lai! He's been following their every move.\n\nConnelly requested you specifically to assist him in gathering some vital intelligence.\n\nHe sent along a disguise for you. Make sure you put it on before approaching the camp! It will no doubt be heavily guarded.\n\nHe insists you will know him when you see him. Something about your keen eye for details...\n\nGo talk to Fennie over there for a drop-off.", sourceObjective = "Meet Connelly in Kun-Lai Summit. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32383] = { id = 32383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bugging Out", description = "I've managed to plant a few bugs around the camp, but there could always be more.\n\nI disguised the bugs to look like statues. They blend in perfectly with the other artifacts lying around.\n\nYour disguise should allow you to move freely around the camp. Just don't go near the dog and don't linger around Garrosh! Nero and Garrosh will see through your disguise.\n\nIf you get caught I can't help you. I can't compromise the mission!", sourceObjective = "Plant the Cleverly Disguised Bugs in the large tent, near the small tents, and in the supplies.", sourceObjectiveStatus = "unverified-source-field" }
quests[32384] = { id = 32384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapping the Leader", description = "It is time to make our move. Go to the Tomb of Shadows, weaken him, and take him captive.\n\nI will stay here in case Garrosh arrives. He must be delayed so that we can take our prize before he destroys it in his anger.\n\nHurry!", sourceObjective = "Weaken and capture Shan Kien at the Tomb of Shadows in Kun-Lai Summit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32388] = { id = 32388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Command", description = "There's an orc general I've been keeping a close eye on. Warlord Bloodhilt curried a lot of favor with Garrosh Hellscream by beating back an Alliance advance in Southern Barrens. He's now entrenched within the fortress at Domination Point.\n\nI doubt the Alliance can take him out. But... you've proven me wrong before.\n\nIf you wish to finish him off, bring friends. Lots of friends.", sourceObjective = "Kill Warlord Bloodhilt at Domination Point in Krasarang Wilds. You will need a group.", completion = "<Wrathion grins.>\n\nYou were being tested, {class}. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Alliance is fortunate to have you.", sourceObjectiveStatus = "unverified-source-field" }
quests[32389] = { id = 32389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lion Roars", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", sourceObjective = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, {name}.\n\nNeither does your Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[32390] = { id = 32390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Packmaster", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on your King. Would you be interested to hear what I've learned?", sourceObjective = "Speak with Wrathion.", progress = "<Three darkly shimmering gems rest in an ornate silk-lined chest. One of them is yours.>", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>", sourceObjectiveStatus = "unverified-source-field" }
quests[32391] = { id = 32391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Korune", description = "Garrosh sent a hundred riders to search the northern coast of Kun-Lai Summit, to seek a mogu crypt matching the one you saw in Shan Kien's memory.\n\nOut of those, one found the resting place of the Divine Bell.\n\nBlademaster Ishi is leading an advance party to secure the bell now.\n\nGo and assist him. Defend that artifact from anyone who might stand in your way!\n\nSpeak to Tak-Tak without delay. He can take you there.", sourceObjective = "Find Ishi at the Ruins of Korune. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32392] = { id = 32392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine Bell", description = "If the Alliance thought they could steal the Divine Bell from us, they were wrong!\n\nEven now, we have them trapped in the crypts beneath us.\n\nDeath will be the price they pay for defying us.\n\nCome, {class}. Let us show them the error of their ways.", sourceObjective = "Kill Sarannha Skyglaive.", sourceObjectiveStatus = "unverified-source-field" }
quests[32393] = { id = 32393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Korune", description = "It's time for our boldest move yet, {name}.\n\nSince you acquired intel on the location of the Divine Bell, we've amassed a top team to excavate the artifact without delay.\n\nCommander Sarannha Skyglaive leads the expedition into the northern-most reaches of Kun-Lai Summit.\n\nJoin them at once, and use whatever skills you need to make the endeavor a success.\n\nGood luck, {class}. I don't need to tell you how important this mission is to the Alliance.\n\nSpeak to Fennie. She'll get you there quickly.", sourceObjective = "Find Sarannha Skyglaive at the Ruins of Korune. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32394] = { id = 32394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine Bell", description = "There's no telling what lies below, so I will lead the initial scouting party myself.\n\nIf your report was correct, then the Korune mogu hid the Divine Bell in the rooms below our very feet.\n\nI have a feeling they would not have left such a precious artifact unguarded.\n\nI could use a capable {class} such as yourself to watch my back. Let me know when you're ready.", sourceObjective = "Kill Dreadweaver Avartu and recover the Divine Bell.", sourceObjectiveStatus = "unverified-source-field" }
quests[32397] = { id = 32397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Won't Even Miss It", description = "I've noticed Garrosh and that Reliquary blood elf carrying around some sort of journal.\n\nThe journal is never more than a stone's throw away. It must be important!\n\nIf you can cause enough of a distraction, you may be able to swipe the journal off the table.\n\nThese yaks might just do the trick. Give one of 'em a tap and they'll do the rest.\n\nJust be ready to move fast!", sourceObjective = "Create a distraction in the camp and steal the Weathered Journal.", sourceObjectiveStatus = "unverified-source-field" }
quests[32398] = { id = 32398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bell Speaks", description = "Your efforts have culminated in this moment, {class}.\n\nWarchief Garrosh gathers the most elite champions of the Horde in Kun-Lai Summit to witness the ringing of the Divine Bell.\n\nYou have more than earned the right to participate.\n\nGo now. The dawn of the new Horde begins today.\n\nSpeak to Tak-Tak. He should be able to secure your travel arrangements.", sourceObjective = "Find Malkorok at Emperor's Reach. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32399] = { id = 32399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Darkest Shadow", description = "It is time, {name}. We have traveled a long path to reach this moment.\n\nToday, our Warchief, Garrosh Hellscream, will change the course of our people's history forever.\n\nToday, we witness the birth of Garrosh's Horde!\n\nDo not let anything interfere with the ceremony!", sourceObjective = "Witness the ringing of the Divine Bell.", sourceObjectiveStatus = "unverified-source-field" }
quests[32400] = { id = 32400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bell Speaks", description = "Horde forces are amassing in huge numbers at the Emperor's Reach, high up in the mountains of Kun-Lai Summit.\n\nThe area is an ancient mogu palace, and certainly a source of untold power.\n\nThis can only mean one thing. Garrosh is going to use the Divine Bell, and Anduin... and the Harmonic Mallet... are both missing.\n\nI have no doubt that the fool boy went north by himself.\n\nI don't have time to gather an elite force to detain him. You must go and stop Anduin.\n\nFennie can take you.", sourceObjective = "Find Anduin at Emperor's Reach. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32401] = { id = 32401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Darkest Shadow", description = "Garrosh is right over there, and he's going to ring that bell at any moment.\n\nWe don't have time to wait for my father's army. This is our only chance to stop him!\n\nI'll attempt to appeal to his senses before resorting to using the Harmonic Mallet.\n\nCharge in whenever you're ready, {name}. I'll be right behind you.", sourceObjective = "Defeat Ishi and destroy the Divine Bell.", sourceObjectiveStatus = "unverified-source-field" }
quests[32402] = { id = 32402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Situation In Dalaran", description = "The night elves learned that the Divine Bell was stolen. This much we anticipated.\n\nHowever, they've also found out that the \"neutral\" Sunreavers of Dalaran were complicit. Now, we've got a situation.\n\nI need you to go to Dalaran. Speak with Kromthar for a ride. You are to rendezvous with Grand Magister Rommath once you arrive.", sourceObjective = "Speak with Kromthar to obtain a ride to Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[32403] = { id = 32403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Starts in the Sewers", description = "Compared to the rest of the city, this part of the sewers is relatively calm. This is good - we can extract more Sunreavers in peace than we can in war.\n\nFind as many citizens as you can. Tell them that it is not safe here, that they must leave the city at once.\n\nAnd try to stay clear of the Silver Covenant. We don't want to cause a scene if we can avoid it. Not yet, anyhow.", sourceObjective = "Evacuate 9 Sunreaver Citizens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32404] = { id = 32404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violence in the Arena", description = "As I suspected, it gets worse up ahead. The Silver Covenant is outright attacking innocent Sunreavers!\n\nThis cannot stand. While our prime directive is to rescue Aethas Sunreaver, we must also protect as many blood elves as we can.\n\nI will continue to scout ahead. Fight well, {class}!", sourceObjective = "Slay 6 Silver Covenant Enforcers and 4 Silver Covenant Spellbows.", sourceObjectiveStatus = "unverified-source-field" }
quests[32405] = { id = 32405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Silver Covenant", description = "Every Sunreaver Jaina expels from this city is a new blade that fights for the Horde. For US.\n\nI'm off to gather more strong elves. You've proven your hand in combat thus far - go take care of that creep in the black market.\n\nWhen you're done, we'll meet at the ramp and prepare to go aboveground.", sourceObjective = "Slay Sorin Magehand.", sourceObjectiveStatus = "unverified-source-field" }
quests[32406] = { id = 32406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tactical Assault", description = "If we're to survive up above ground, we're going to need a base of operations.\n\nI'm going to try to take the center of the city. It's risky, but hopefully Jaina and the Silver Covenant won't expect it.\n\nStay by my side now, {name}.", sourceObjective = "Follow Grand Magister Rommath into the center of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[32408] = { id = 32408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Covenant's Stronghold", description = "I have it on good authority that Archmage Aethas Sunreaver is being held in the Silver Enclave, home of the Silver Covenant. Arcanist Rathaella holds him in captivity.\n\nMost Covenant agents are out slaughtering Sunreavers right now, which means our chance is ripe. Slay Rathaella, and spring Aethas from his prison.", sourceObjective = "Slay Arcanist Rathaella.", sourceObjectiveStatus = "unverified-source-field" }
quests[32409] = { id = 32409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirin Tor's True Colors", description = "Any pretense that the Kirin Tor might have had at being a \"neutral\" group can officially be discarded. I'm now hearing that Jaina's got Alliance troops stowed away near Antonidas Memorial.\n\nThe area's free of Sunreavers, but it still makes my blood boil to see such blatant favoritism from the Kirin Tor.\n\nGo visit the memorial, {name}... and give those Alliance dogs a good kick on your way through.", sourceObjective = "Slay Lieutenant Corwin and 10 of his troops.", sourceObjectiveStatus = "unverified-source-field" }
quests[32410] = { id = 32410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Landing", description = "We can rescue as many Sunreavers as we want, but if they can't escape, then there's no point.\n\nThe Silver Covenant will certainly be subduing and killing the Sunreavers' dragonhawks. Put a stop to it.", sourceObjective = "Free 6 Sunreaver Dragonhawks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32411] = { id = 32411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Remaining Sunreavers", description = "There's still a number of significant Sunreavers who haven't been accounted for. Odds are that they're in the Sunreaver's Sanctuary, caught by surprise.\n\n<Rommath hands you an artifact, clearly made by blood elf hands.>\n\nThe place is crawling with Silver Covenant. You'll need to get in, use the Tear to evacuate the VIPs, and then get out.\n\nStay alive, {name}.", sourceObjective = "Use the Tear of the Sin'dorei on Uda the Beast, High Arcanist Savor, Magister Hathorel, Magister Surdiel, and Magistrix Vesara.", sourceObjectiveStatus = "unverified-source-field" }
quests[32412] = { id = 32412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Grasp", description = "We've looked everywhere he's likely to be, except for one place: the Violet Citadel.\n\nFind out if Archmage Aethas is being held within the citadel, {name}. We may get lucky. If not... at least we saved a number of lives today.", sourceObjective = "Slay Mage-Commander Zuros, then escape from Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[32413] = { id = 32413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Return to Krasarang", description = "Wherever your loyalties might lie - with Rommath and I, with Garrosh, or elsewhere - one thing is true: your acts today were truly heroic.\n\nI can arrange for your transport back to Krasarang Wilds. Speak with me if you would like passage back to Pandaria, {name}.", sourceObjective = "Report to General Nazgrim at Domination Point in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32414] = { id = 32414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus Attacked?", description = "As you know, our night elven allies moved the Divine Bell you retrieved to Darnassus for safekeeping and study. Moments ago, they portaled some Highbourne mages over here to ask for backup. Details are hazy - some sort of stealth attack on the city?\n\nI don't know what to make of it, but Jaina Proudmoore is already on the scene and I suspect they need all the help they can get.\n\nSpeak to Seamus Goldenkicks over there for a quick portal to Darnassus. Find Jaina!", sourceObjective = "Speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus, then speak with Jaina once you arrive.", sourceObjectiveStatus = "unverified-source-field" }
quests[32416] = { id = 32416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Resolution", description = "For too long, I have toiled to mend fences between Alliance and Horde. Time and time again, I've given the Horde the benefit of the doubt - and time and time again, they stab me in the back.\n\nI refuse to be betrayed again! If the Horde intends to use the Kirin Tor as a weapon against the Alliance, then they have no place in Dalaran.\n\nCome with me, {name}.", sourceObjective = "Use the portal from Darnassus to Dalaran, then speak with Vereesa Windrunner on the other side.", sourceObjectiveStatus = "unverified-source-field" }
quests[32417] = { id = 32417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Cleaning", description = "Jaina's doing a good job taking care of Sunreavers above ground, but there's still plenty rooting around in the sewers.\n\nGo find those lying rats and exterminate them!", sourceObjective = "Slay 12 Sunreavers in the Dalaran Sewers.", sourceObjectiveStatus = "unverified-source-field" }
quests[32418] = { id = 32418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfair Trade", description = "Most shopkeepers in the Magus Commerce Exchange have sided with the Silver Covenant, but there remain a few holdouts that must be taken care of.\n\n<Vereesa shows you a list of names.>\n\nThey will not go easily.", sourceObjective = "Slay Inkmaster Aelon, Tolyria, Gearmage Astalon, and Sintharia Cinderweave.", sourceObjectiveStatus = "unverified-source-field" }
quests[32419] = { id = 32419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Hide", description = "The Sunreaver's Sanctuary is still crawling with those Horde-loving Sunreavers.\n\nJaina will have sent the reasonable ones to the Violet Hold. The rest refuse to leave, raising their weapons against us.\n\nShow them the cost of their defiance. They now face the judgment of the Alliance, the Silver Covenant, and the Kirin Tor!", sourceObjective = "Slay 16 Sunreavers in the Sunreaver's Sanctuary.", sourceObjectiveStatus = "unverified-source-field" }
quests[32420] = { id = 32420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cashing Out", description = "I just saw one of the Sunreavers - Brasael, I think his name was - running off in the direction of the bank to the north. No doubt he's trying to gather whatever assets he can before he leaves.\n\nHead him off and make sure he doesn't steal any resources from our coffers. He relinquished whatever funds he left in the bank when he and his Sunreaver kind betrayed us.", sourceObjective = "Slay Magister Brasael.", sourceObjectiveStatus = "unverified-source-field" }
quests[32421] = { id = 32421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Run", description = "Compliant Sunreavers will be sent to the Violet Hold. Defiant ones are put to the sword.\n\nNONE are to escape.\n\nThe Sunreavers keep their dragonhawk mounts on Krasus' Landing. Take this dust, and use it to render them incapable of flying.\n\nOr kill them. I don't care.", sourceObjective = "Render 5 Sunreaver Dragonhawks incapable of flying.", sourceObjectiveStatus = "unverified-source-field" }
quests[32423] = { id = 32423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Had To Be Done", description = "Thank you for your aid today, {name}. I will be handling the purge from here on out.\n\nJaina will soon be off to Lion's Landing, to speak with King Varian. She asked for your attendance.", sourceObjective = "Speak with Vereesa Windrunner to travel to Lion's Landing, then speak with King Varian Wrynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[32426] = { id = 32426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirred, Not Shaken", description = "Alright, I'll tell you how to find Connelly.\n\nAgent Connelly is currently posing as the high roller, Professor Kilt. He spends most of his time in the Boom Room. Rumor has it he's after one of the fighters for some long forgotten betrayal.\n\nUnfortunately, the lounge is by invitation only. Lucky for you I just happen to have an invitation.\n\nTry not to look too obvious when you walk past the bouncers. If you get caught you didn't get this pass from me.\n\nIn fact you and I have never met!", sourceObjective = "Find Professor Kilt in the Boom Room in Bizmo's Brawlpub.", completion = "So the SI: 7 needs a reminder in what the word retirement means?\n\nI suppose they wouldn't be comin' to me if the situation weren't dire.\n\nI'll help, but I'll need a few days to gather some intel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32427] = { id = 32427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. Your Warchief aims to impress the Pandaren with the full might of the Horde's military. He will lay claim to the resources of this land, with or without Pandaren aid.\n\nI understand your leader's aims, but I really want to understand the Warchief himself. What drives him? And where is the Horde ultimately going? I'd like to talk to you about this leader of yours.", sourceObjective = "Speak with Wrathion at the Tavern in the Mists.", progress = "I love a good chat.", completion = "Like all great leaders, Garrosh has greatly extended himself. Just what is he ultimately capable of?\n\nMore importantly, what YOU are capable of? Fresh bloodshed along the coast gives us an opportunity to find out...", sourceObjectiveStatus = "unverified-source-field" }
quests[32428] = { id = 32428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Spirit Tamer", description = "Legend tells of legendary pandaren spirits that roam the lands of Pandaria.  Find them and defeat them in a pet battle.", sourceObjective = "Defeat all of the Pandaren Spirits in a pet battle.", completion = "I can't belive you took out those spirits!", sourceObjectiveStatus = "unverified-source-field" }
quests[32429] = { id = 32429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Horde deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", sourceObjective = "Kill Alliance forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Alliance buckles under Horde might, although their King refuses to break.\n\nI believe it is time for a more substantial challenge...", sourceObjectiveStatus = "unverified-source-field" }
quests[32430] = { id = 32430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Command", description = "There's an Alliance dwarf I've been keeping a close eye on. High Marshal Twinbraid proved to be a nuisance in Southern Barrens when he struck back at the Horde after the loss of Bael Modan. He's now entrenched within the Alliance stronghold in Lion's Landing, helping to orchestrate the Krasarang counter-offensive.\n\nOnly a legendary group of Horde heroes could possibly defeat him.\n\nIf you wish to finish him off, bring friends. Lots of friends.", sourceObjective = "Kill High Marshal Twinbraid at Lion's Landing in Krasarang Wilds. You will need a group.", completion = "<Wrathion grins.>\n\nYou were being tested, {class}. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Horde is fortunate to have you.", sourceObjectiveStatus = "unverified-source-field" }
quests[32431] = { id = 32431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory to the Horde", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", sourceObjective = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, {name}.\n\nNeither does this Horde of yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[32432] = { id = 32432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul of the Horde", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on Garrosh Hellscream. Would you be interested to hear what I've learned?", sourceObjective = "Speak with Wrathion.", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>", sourceObjectiveStatus = "unverified-source-field" }
quests[32434] = { id = 32434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Pandaren Spirit", description = "You're back!  Up for another battle with me?", sourceObjective = "Defeat Burning Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!", sourceObjectiveStatus = "unverified-source-field" }
quests[32435] = { id = 32435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Place", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to get second place!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
quests[32436] = { id = 32436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Place", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to be awarded the third and final prize!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
quests[32439] = { id = 32439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowing Pandaren Spirit", description = "You're back!  Up for another battle with me?", sourceObjective = "Defeat Flowing Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!", sourceObjectiveStatus = "unverified-source-field" }
quests[32440] = { id = 32440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispering Pandaren Spirit", description = "You're back!  Up for another battle with me?", sourceObjective = "Defeat Whispering Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!", sourceObjectiveStatus = "unverified-source-field" }
quests[32441] = { id = 32441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundering Pandaren Spirit", description = "You're back!  Up for another battle with me?", sourceObjective = "Defeat Thundering Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!", sourceObjectiveStatus = "unverified-source-field" }
quests[32446] = { id = 32446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dis-Assembly Required", description = "Those shredders are becoming a problem down there, {class}.\n\nWe've sent in the Mecha-Pounders, but it just isn't enough. They're getting damaged faster than we can repair 'em!\n\nI happened upon this strange remote while scouting. With a little bit of re-configurin' I think we can use it.\n\nTry usin' it on the Jungle Shredders. Hopefully it will destroy them and then you can bring me the scrap metal.", sourceObjective = "Destroy the Jungle Shredders using the Re-Configured Remote and then collect 6 pieces of Scrap Metal.", progress = "So what did that remote do?", completion = "Goblin construction leaves somethin' to be desired, but it'll have to do. Good work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32448] = { id = 32448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ties with the Past", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to recover the essential ingredient for me. We need the spirit essence of a mogu that lived in the time of the memory we wish to see.\n\nYou should be able to find just such a spirit inside the Path of Conquerors, to the northeast.", sourceObjective = "Recover the Spirit Essence of Varatus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32449] = { id = 32449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Ogudei", description = "Our scouts at Sparkrocket Outpost have reported some new activity near an area called the Ruins of Ogudei.\n\nWe need to gather intelligence on what it is the Alliance are doing, and more importantly what it is they found. We cannot afford to have any unknowns.\n\nMeet up with Belloc Brightblade in Sparkrocket Outpost and find out what he knows.", sourceObjective = "Report to Belloc Brightblade in Sparkrocket Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[32450] = { id = 32450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time Is Now!", description = "Now we take the fight to them, {class}!\n\nReport to Shademaster Kiryn in Sparkrocket Outpost. She will have your orders.\n\nNow we'll see how they handle the full might of the Horde rushing at their precious keep!", sourceObjective = "Report to Shademaster Kiryn in Sparkrocket Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[32451] = { id = 32451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send A Message", description = "It's time we show these Horde mongrels the full strength of the Alliance! Today we bring the battle to their door.\n\nReport to Admiral Rogers aboard the Skyfire. She will have further instructions.\n\nGood luck out there, {class}. Do the Alliance proud!", sourceObjective = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", completion = "The battle is already underway, {class}. Let's get you out there!", sourceObjectiveStatus = "unverified-source-field" }
quests[32452] = { id = 32452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were Goblins", description = "We're fighting a war on all fronts, {class}. Even Pandaria itself needs our protection.\n\nThe Bilgewater goblins are destroying land that doesn't belong to them. They must be stopped!\n\nReport to Sky Admiral Rogers aboard the Skyfire. From her vantage point she should have a good idea of where their weak spots are.", sourceObjective = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", completion = "It's about time we dealt with this nuisance. Those Bilgewater runts need to be taught a lesson!", sourceObjectiveStatus = "unverified-source-field" }
quests[32455] = { id = 32455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silence", description = "D..did we... do it?\n\n<Anduin mumbles the words, even though the effort clearly costs him.>\n\nL..look... in.. my... bag...\n\nUse... flare...", sourceObjective = "Use the Alliance Flare Gun.", sourceObjectiveStatus = "unverified-source-field" }
quests[32457] = { id = 32457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunder King", description = "Are you aware of recent events in Kun-Lai Summit? The Zandalari have landed on the northern shores in great numbers and have set about renewing old alliances. To that end, they have resurrected The Thunder King.\n\nEven among the mogu, the name of the first emperor commands awe and fear. The Thunder King founded a vast empire of slavery and suffering... but also of power, riches, and splendor.\n\nWe will take the fight to him soon. Find me when your faction makes its move.", sourceObjective = "Contact Wrathion on the second floor of the Tavern in the Mists in the Veiled Stair.", sourceObjectiveStatus = "unverified-source-field" }
quests[32458] = { id = 32458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! My father's fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our ships to these shores. We just need to collect charms of good fortune to make it happen.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", sourceObjective = "Collect Charms of Good Fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[32459] = { id = 32459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! The Horde fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our brothers and sisters to these shores. We simply need to collect charms of good fortune to gain fortune's favor.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", sourceObjective = "Collect Charms of Good Fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[32460] = { id = 32460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Thieves", description = "We WILL get to the bottom of this.\n\n{name}, you're coming with me. We'll search every inch of this city if we have to, but we'll find out how they took the bell... and where.\n\nI'm picking up traces of arcane magic here... we need to follow the trail!", sourceObjective = "Help Jaina discover who took the Divine Bell, and where they took it. You may speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32461] = { id = 32461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order of the Cloud Serpent", description = "Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent.\n\nBefore you may fly the skies on this powerful creature, you must first earn the skill to ride it.\n\nThe Order of the Cloud Serpent can teach you the knowledge that you seek.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", sourceObjective = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", completion = "Ah, have you come to join the Order?", sourceObjectiveStatus = "unverified-source-field" }
quests[32474] = { id = 32474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, {class}. I am watching.\n\nThe Pandaren, like the Alliance, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, {name}!", sourceObjective = "Gain the \"A Test of Valor\" Achievement by earning a total of 1600 Valor Points.", completion = "<Wrathion nods slowly.>\n\nYes, {name}. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change.", sourceObjectiveStatus = "unverified-source-field" }
quests[32476] = { id = 32476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, {class}. I am watching.\n\nThe Pandaren, like the Horde, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, {name}!", sourceObjective = "Gain the \"A Test of Valor\" Achievement by earning a total of 1600 Valor Points.", progress = "Brave, brave {class}. How goes the fight?", completion = "<Wrathion nods slowly.>\n\nYes, {name}. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change.", sourceObjectiveStatus = "unverified-source-field" }
quests[32489] = { id = 32489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in the Undercity.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", sourceObjective = "Crush 75 Ihgaluk Roaches.", sourceObjectiveStatus = "unverified-source-field" }
quests[32491] = { id = 32491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", sourceObjective = "Destroy 3 Fetid Meat Piles.", sourceObjectiveStatus = "unverified-source-field" }
quests[32492] = { id = 32492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Cauldrons" }
quests[32493] = { id = 32493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They All Fall Down", description = "The Zandalari do not tolerate weakness in their ranks, {class}.\n\nThose that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds.\n\nI wish to study their essence. For this I will need your help.\n\nTake this resonance crystal and siphon the spirits from the sentry corpses.\n\n Do not allow them to escape!", sourceObjective = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari Spirits trapped within.", sourceObjectiveStatus = "unverified-source-field" }
quests[32494] = { id = 32494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Play", description = "The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power.\n\nTwo such items exist here. To be specific, two masks, worn by two brothers.\n\nSpiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed.\n\nKill them and return their masks to me. I will make sure the masks are disposed of.", sourceObjective = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32495] = { id = 32495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", sourceObjective = "Kill Kaida the Bloodletter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32496] = { id = 32496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!" }
quests[32497] = { id = 32497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Dread Wastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[32498] = { id = 32498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[32499] = { id = 32499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32500] = { id = 32500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Kun-Lai Summit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32501] = { id = 32501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Townlong Steppes.", sourceObjectiveStatus = "unverified-source-field" }
quests[32502] = { id = 32502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Midsummer Bonfire in Valley of the Four Winds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32503] = { id = 32503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!" }
quests[32504] = { id = 32504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Secrets of Stormwind", description = "Send undercover forces into the heart of enemy territory in an effort to learn of their plans." }
quests[32505] = { id = 32505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbled Chamberlain", description = "You there! Assist me.\n\nIn life I was the Royal Chamberlain for his majesty, the Thunder King. For my dedication, I was condemned to this stone form, forever forced to watch over a portion of his wealth.\n\nSomeone has desecrated my glorious body and sent pieces of it across the island. The thought of spending an eternity as nothing more than a head depresses me.\n\nSearch the island, recover these pieces and I shall grant you one of his majesty's treasures.", sourceObjective = "Recover the Shoulder, Head, Staff, Hair and Torso of the Chamberlain.", sourceObjectiveStatus = "unverified-source-field" }
quests[32506] = { id = 32506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", sourceObjective = "Recover a Wild Ptrerrorwing Hatchling.", sourceObjectiveStatus = "unverified-source-field" }
quests[32507] = { id = 32507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Sunreavers behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", sourceObjective = "Go to Ihgaluk Crag and slay a Skumblade saurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32509] = { id = 32509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame" }
quests[32510] = { id = 32510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame" }
quests[32517] = { id = 32517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", sourceObjective = "Stop the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[32521] = { id = 32521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?", sourceObjective = "Kill Nurkala, the Zandalari War Leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[32522] = { id = 32522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for me?", sourceObjective = "Kill Horgak the Enslaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32523] = { id = 32523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beast Pens", description = "We need to counter the beasts the Zandalari are using to strike at our camp. I have dispatched Scout Captain Elsia to the Beast Pens along with some war mages to provide cover.\n\nGo and find her east of here near the breaches in the wall and help her trim down the cavalry and siege beasts being levied against us.\n\nThey are masked, so look for the shimmers of their magical cloaking spells.", sourceObjective = "Find Scout Captain Elsia at the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32524] = { id = 32524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beating of Troll Drums", description = "Do you hear that, {class}? The beating of war drums in the distance. The Zandalari are preparing for us.\n\nLet's not give them the luxury of time to organize their defenses. We need to push the attack now!\n\nReport to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.", sourceObjective = "Locate Scout Captain Elsia within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32525] = { id = 32525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Enemy", description = "The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", sourceObjective = "Burn 8 Mummified Remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[32526] = { id = 32526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nAlliance or Horde, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", sourceObjective = "Save 6 Silver Covenant Scouts or Sunreaver Scouts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32527] = { id = 32527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", sourceObjective = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", sourceObjectiveStatus = "unverified-source-field" }
quests[32528] = { id = 32528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Crypts", description = "Every day, we uncover additional relics from the Court of Bones.\n\nRecently, we discovered this scroll amongst the gravestones in one of the deepest crypts.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", sourceObjective = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed.", sourceObjectiveStatus = "unverified-source-field" }
quests[32529] = { id = 32529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise.\n\nThere is no time to delay. You must stop their ritual at once.", sourceObjective = "Stop the Shan'ze Thundercallers' ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32531] = { id = 32531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", sourceObjective = "Disrupt the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[32532] = { id = 32532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", sourceObjective = "Kill 15 Risen Ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32536] = { id = 32536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", sourceObjective = "Check in with Magister Yalis, Magister Lyanis, and Magistrix Sanal.", sourceObjectiveStatus = "unverified-source-field" }
quests[32538] = { id = 32538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heinous Sacrifice", description = "Some of the strongest of the spiritbinders perform heinous rites to their wretched gods.\n\nWe've devised a method to destroy their altars, so the difficult task will be getting to each altar alive.\n\nVenture into the depths of Za'Tual and destroy their altars.", sourceObjective = "Destroy the Zandalari's sacrificial altars.", sourceObjectiveStatus = "unverified-source-field" }
quests[32539] = { id = 32539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Offerings", description = "The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process.\n\nDestroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.", sourceObjective = "Destroy 6 Zandalari Offerings.", sourceObjectiveStatus = "unverified-source-field" }
quests[32540] = { id = 32540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Loa", description = "If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil.\n\nPlease, venture into the troll camp and put a stop to these unspeakable rituals.", sourceObjective = "Slay 2 Harbingers of the Loa.", sourceObjectiveStatus = "unverified-source-field" }
quests[32541] = { id = 32541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventing a Future Threat", description = "It pains me to think of the torture the poor skyscreamers  must endure as the trolls train them to become implements of war.\n\nThe hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.", sourceObjective = "Frighten 12 Hatchling Skyscreamers by running near them.", sourceObjectiveStatus = "unverified-source-field" }
quests[32542] = { id = 32542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surgical Strike", description = "Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day.\n\nDispose of these threats in Za'Tual, {race}, and watch the might of the trolls weaken.", sourceObjective = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32543] = { id = 32543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangers of Za'Tual", description = "The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, {name}.\n\nEnter Za'Tual to and show them the risks associated with opposing the likes of you.", sourceObjective = "Slay 12 Trolls in Za'Tual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32544] = { id = 32544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrible Ptorment", description = "One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters.\n\nKill those that inflict such torment on the creature and we can only hope that it will return to the skies.", sourceObjective = "Free the Tormented Skyscreamer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32547] = { id = 32547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in Booty Bay.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", sourceObjective = "Crush 75 Ihgaluk Roaches.", sourceObjectiveStatus = "unverified-source-field" }
quests[32548] = { id = 32548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", sourceObjective = "Destroy 3 Fetid Meat Piles.", sourceObjectiveStatus = "unverified-source-field" }
quests[32549] = { id = 32549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Kirin Tor behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", sourceObjective = "Go to Ihgaluk Crag and slay a Skumblade saurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32550] = { id = 32550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.", sourceObjective = "Defeat 10 Zandalari trolls in the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32551] = { id = 32551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compy Stomp", description = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", sourceObjective = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32552] = { id = 32552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", sourceObjective = "Defeat a Loa Speaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[32553] = { id = 32553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn vs Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", sourceObjective = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[32554] = { id = 32554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", sourceObjective = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32557] = { id = 32557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Enemy Hands", description = "Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands.\n\nThe Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage.\n\nSteal as many of the weapons as you can find.", sourceObjective = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32558] = { id = 32558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All In the Family", description = "Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated.\n\nTheir power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on.\n\nWe must deal with the brothers and destroy their masks before they fall into the wrong hands.", sourceObjective = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32560] = { id = 32560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep It Secret", description = "The Zandalari here are a threat to our campaign, {class}.\n\nTheir use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence.\n\nWe cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic.\n\nTheir numbers must be thinned. I will leave this task to you.", sourceObjective = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32567] = { id = 32567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beast Pens", description = "I do not want to see another Zandalari beast rider breach our defenses!\n\nI have dispatched Scout Captain Daelin and some war mages to the Beast Pens northwest of here. Their mission is to infiltrate and harass the Zandalari siege and cavalry units. I want you to join them and lend your expertise.\n\nKeep an eye out for the tell tale shimmer of their magical cloaking spell.", sourceObjective = "Find Scout Captain Daelin at the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32568] = { id = 32568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time To Rest", description = "We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold.\n\nNow, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.", sourceObjective = "Locate Scout Captain Daelin within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32571] = { id = 32571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", sourceObjective = "Recover a Wild Ptrerrorwing Hatchling.", sourceObjectiveStatus = "unverified-source-field" }
quests[32572] = { id = 32572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", sourceObjective = "Kill 6 Animated Warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32573] = { id = 32573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.", sourceObjective = "Kill 7 Shan'ze mogu in the Diremoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32574] = { id = 32574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", sourceObjective = "Kill the Mighty Devilsaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[32575] = { id = 32575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", sourceObjective = "Destroy the Zandalari Colossus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32579] = { id = 32579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Magic", description = "The scouts have spotted a dangerous Zandalari just this side of Za'Tual. We need someone capable to see him dispatched. Are you up to the task?", sourceObjective = "Kill Arcweaver Jor'guva.", sourceObjectiveStatus = "unverified-source-field" }
quests[32581] = { id = 32581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "The scryers have spotted a mogu leader at the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for us?", sourceObjective = "Kill Horgak the Enslaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32582] = { id = 32582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", sourceObjective = "Kill Zur'chaka the Bonecrafter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32586] = { id = 32586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Capacitor", description = "The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore.\n\nIf you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons.\n\nOh, also, kill whoever is in charge, will you?", sourceObjective = "Destroy the 3 lightning drills in the Ghost Iron Mines, and kill Metal Lord Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32587] = { id = 32587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", sourceObjective = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32588] = { id = 32588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Her Magic-ey Secret Service", description = "Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines.\n\nThey were captured, and are being subjected to who-knows-what kind of awful tortures.\n\nYou must free them and kill whoever captured them. We don't leave anyone behind!", sourceObjective = "Rescue the three captured Kirin Tor agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32590] = { id = 32590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me Upstairs", description = "There's someone I'd like you to meet. Stormwind's own crown prince recently paid a visit to this humble inn. I've instructed my guards to defend him from any Horde aggression - I don't want to draw any undue attention to myself.\n\nHe and I have been discussing world events, such as the battle along the southern shores, his encounter with Garrosh, and the upcoming assault on the Thunder King.\n\nCome! Let's talk upstairs...", sourceObjective = "Meet Wrathion upstairs on the second floor of the Tavern in the Mists in the Veiled Stair.", sourceObjectiveStatus = "unverified-source-field" }
quests[32591] = { id = 32591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the First Empire", description = "For two thousand years the mogu ruled this entire land. So brutal was their regime that its name is never uttered aloud: Pandaren call it either the \"Old Kingdom\" or \"First Dynasty.\"\n\nThe Thunder King was its founder and first emperor. He amassed enormous power on what is now the Isle of Thunder.\n\nHis time has passed, {name}. We should claim some of his power for ourselves. Gather mogu relics for me from the Throne of Thunder, and amass some trillium - I have a plan!", sourceObjective = "Collect 20 Secrets of the Empire and 40 Trillium Bars.", sourceObjectiveStatus = "unverified-source-field" }
quests[32592] = { id = 32592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Need a Champion", description = "You are a superb representative of your people, {race}. But I need someone special. I have big plans. And to enact them I will need a champion to carry my flame to the four corners of the world.\n\nAre you the one?\n\nProve it to me on the Isle of Thunder! Lay waste to any mogu, Zandalari, or saurok that you find. Impress me!", sourceObjective = "Earn Exalted Reputation with the Black Prince by defeating mogu, Zandalari, and saurok enemies on the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32600] = { id = 32600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Prophecy", sourceObjective = "Bring The Zandalari Prophecy to Lorewalker Cho.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[32601] = { id = 32601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumbles of Thunder", sourceObjective = "Bring the Rumbles of Thunder to Lorewalker Cho.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[32602] = { id = 32602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods and Monsters", sourceObjective = "Bring the Gods and Monsters to Lorewalker Cho.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[32603] = { id = 32603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable", description = "Have you ever read the great Pandaren book of fables?  Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.", sourceObjective = "Defeat the Elite Battle Pets of the Pandaren fables.", completion = "You found them all? Amazing! So the stories ARE true! Perhaps you will write the next great Pandaren fable based on your own incredible journey!", sourceObjectiveStatus = "unverified-source-field" }
quests[32604] = { id = 32604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable Book I", description = "The stories of Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?", sourceObjective = "Defeat Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga.", completion = "I bow to you who continues to walk in the footfalls of the great Pandaren fables.", sourceObjectiveStatus = "unverified-source-field" }
quests[32605] = { id = 32605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.", sourceObjective = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32606] = { id = 32606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.", sourceObjective = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32613] = { id = 32613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giant Dinosaur Bone" }
quests[32614] = { id = 32614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Giant Dinosaur Bones" }
quests[32615] = { id = 32615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many More Giant Dinosaur Bones" }
quests[32616] = { id = 32616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Large Pile of Giant Dinosaur Bones" }
quests[32617] = { id = 32617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mountain of Giant Dinosaur Bones" }
quests[32618] = { id = 32618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Randal Hunter.", completion = "Don't forget to buy your mount while you are here!  Katie Hunter can be found here in camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[32621] = { id = 32621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Steel", description = "Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?", sourceObjective = "Investigate the Thunder Forge to find the Secrets of Lightning Steel.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[32622] = { id = 32622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intro Flight" }
quests[32640] = { id = 32640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", sourceObjective = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", sourceObjectiveStatus = "unverified-source-field" }
quests[32641] = { id = 32641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", sourceObjective = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", sourceObjectiveStatus = "unverified-source-field" }
quests[32642] = { id = 32642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Dominance Offensive I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Horde I decided to pass this order your way.\n\nThe Dominance Offensive has requested an order of red blossom leeks.\n\nThe troops down there just can't seem to get enough of them!", sourceObjective = "Plant 8 Red Blossom Leek Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32644] = { id = 32644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault on Shaol'mara", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", sourceObjective = "Complete the Assault on Shaol'mara. Speak to Jaina Proudmoore to begin the attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[32645] = { id = 32645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Operation: Shieldwall I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Alliance I decided to pass this order your way.\n\nOperation: Shieldwall has requested a whole heap of witchberries.\n\nI can't be sure, but I think they have an idea to use them in some sort of weapon.", sourceObjective = "Plant 8 Witchberry Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32646] = { id = 32646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Operation: Shieldwall II", description = "Once your witchberries are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your witchberries will be a part of your faction's efforts in Pandaria!", sourceObjective = "Harvest 8 Ripe Witchberry plants and provide 40 Witchberries for Operation: Shieldwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[32647] = { id = 32647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Golden Lotus I", description = "<Yoon kept this order request short.>\n\nThe Golden Lotus have requested a large number of white turnips.\n\nTheir request mentioned something about trouble-making sprites wreaking havoc on Mistfall Village. Apparently the sprites don't like turnips!", sourceObjective = "Plant 8 White Turnip Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32649] = { id = 32649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Shado-Pan I", description = "<Yoon's writing seems rushed. He must have been excited.>\n\nThe Shado-Pan want crops from you! What an honor indeed!\n\nA request came in this morning for green cabbages. Apparently, they make a rather tasty cabbage soup with them.\n\nOnly the finest will do for the Shado-Pan!", sourceObjective = "Plant 8 Green Cabbage Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32650] = { id = 32650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Shado-Pan II", description = "Well, your work is done for the day! Now to wait for the harvest tomorrow.\n\nOnce your green cabbages are ready to be picked, you'll need only to package them for pick-up.\n\nOnly the finest cabbage will do for the Shado-Pan!", sourceObjective = "Harvest 8 Ripe Green Cabbage plants and provide 40 Green Cabbages for the Shado-Pan", sourceObjectiveStatus = "unverified-source-field" }
quests[32652] = { id = 32652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Skies!", description = "We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari.\n\nSpeak to me when you're ready to learn more.", sourceObjective = "Gain access to the Lightning Vein Mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32653] = { id = 32653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The August Celestials I", description = "<Yoon's familiar writing scrolls across the tattered paper.>\n\nThe trainees out at the Cradle of Chi-Ji are in need of striped melons. Apparently, they use them in their training exercises.\n\nA representative will be by tomorrow to collect whatever striped melons you can spare.", sourceObjective = "Plant 8 Striped Melon Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32654] = { id = 32654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", sourceObjective = "Speak with Lady Jaina Proudmoore, then break into the lower city and secure it for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[32657] = { id = 32657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The August Celestials II", description = "Once your striped melons are ready to be picked, you'll need only to package them for pick-up.\n\nA trainee from the Cradle of Chi-Ji will be along shortly to collect their order.", sourceObjective = "Harvest 8 Ripe Striped Melon plants and provide 40 Striped Melons for the August Celestials.", sourceObjectiveStatus = "unverified-source-field" }
quests[32658] = { id = 32658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The Klaxxi I", description = "<Though Yoon's writing leaves something to be desired, it's nice to still have a little piece of him on the farm.>\n\nAn order came in this morning from the Klaxxi. Strangely enough they are requesting mogu pumpkins for some kind of research.\n\nI find it's best not to ask them too many questions...\n\nBest get started on their order. I'd hate to see what a bug of that size could do to your crops if you don't!", sourceObjective = "Plant 8 Mogu Pumpkin Seeds on Sunsong Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32659] = { id = 32659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The Klaxxi II", description = "Once your mogu pumpkins are ready to be picked, you'll need only to package them for pick-up.\n\nI wouldn't dilly-dally if I were you. The Klaxxi aren't known for their patience!", sourceObjective = "Harvest 8 Ripe Mogu Pumpkin plants and provide 40 Mogu Pumpkins for the Klaxxi.", sourceObjectiveStatus = "unverified-source-field" }
quests[32661] = { id = 32661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Aalun at the entrance to the Exodar on Azuremyst Isle.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Aalun.", completion = "Don't forget to buy your mount while you are here! Torallius is right over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32662] = { id = 32662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Ultham Ironhorn.", completion = "Don't forget to buy your mount while you are here! Veron Amberstill is standing just outside the gates to the Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32663] = { id = 32663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Binjy Featherwhistle.", completion = "Don't forget to buy your mount while you are here! Milli's right over there!", sourceObjectiveStatus = "unverified-source-field" }
quests[32664] = { id = 32664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Jartsam at the Cenarion Enclave in Darnassus.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Jartsam.", completion = "Don't forget to buy your mount while you are here! You can buy one from Lelanai right here.", sourceObjectiveStatus = "unverified-source-field" }
quests[32665] = { id = 32665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Mei Lin north of the Dwarven District in Stormwind.  Don't forget to buy your mount while you are there!", sourceObjective = "Find Mei Lin.", completion = "Don't forget to buy your mount while you are here! You can buy one from Old Whitenose here.", sourceObjectiveStatus = "unverified-source-field" }
quests[32667] = { id = 32667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Softpaws in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", sourceObjective = "Find Softpaws.", completion = "Don't forget to buy your mount while you are here! You can buy one from Turtlemaster Odai here.", sourceObjectiveStatus = "unverified-source-field" }
quests[32668] = { id = 32668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Perascamin at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City. Don't forget to buy your mount while you are there!", sourceObjective = "Find Perascamin.", completion = "Don't forget to buy your mount while you are here! You can buy one from Winaestra just outside.", sourceObjectiveStatus = "unverified-source-field" }
quests[32669] = { id = 32669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", sourceObjective = "Find Kildar.", completion = "Don't forget to buy your mount while you are here! You can buy one from Ogunaro over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32670] = { id = 32670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!", sourceObjective = "Find Kar Stormsinger.", completion = "Don't forget to buy your mount while you are here! You can buy one from Harb Clawhoof over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32671] = { id = 32671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!", sourceObjective = "Find Xar'Ti.", completion = "Don't forget to buy your mount while you are here! You can buy one from Zjolnir over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32672] = { id = 32672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!", sourceObjective = "Find Velma Warnam.", completion = "Don't forget to buy your mount while you are here! You can buy one from Zachariah Post here.", sourceObjectiveStatus = "unverified-source-field" }
quests[32673] = { id = 32673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!", sourceObjective = "Find Revi Ramrod.", completion = "Don't forget to buy your mount while you are here! You can buy one from Kall Worthaton over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32674] = { id = 32674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Maztha, at the Skyway in Orgrimmar.\n\nAnd don't forget to buy a flying mount!", sourceObjective = "Find Maztha.", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Drakma, just behind me.", sourceObjectiveStatus = "unverified-source-field" }
quests[32675] = { id = 32675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Bralla Cloudwing, at the Gryphon Roost in Stormwind.\n\nAnd don't forget to buy a flying mount!", sourceObjective = "Find Bralla Cloudwing.", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Tannec Stonebeak over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[32680] = { id = 32680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives Jaina and the Kirin Tor more of a hold on the Isle.\n\nLor'themar awaits us. Speak to me when you are ready to depart. I will escort you there myself.", sourceObjective = "Travel with Scout Captain Elsia to the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32681] = { id = 32681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives the Sunreavers more of a hold on the Isle.\n\nLady Jaina Proudmoore awaits us. We should not make her wait any longer.\n\nSpeak to me when you are ready to depart. I will escort you there myself.", sourceObjective = "Travel with Vereesa Windrunner to the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32682] = { id = 32682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inherit the Earth", description = "As you know, {name}, I'm getting along in my years. One can't stay a spry young pandaren forever, you know.\n\nI'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon.\n\nHe's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart.\n\nDo you think he'd be interested?", sourceObjective = "Speak to Farmer Yoon.", progress = "Julep and juice, now that's a nice combination!", completion = "Why I just knew you could convince him, {name}. You've set my heart at ease, knowing the Tillers will be in good hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[32684] = { id = 32684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Want Fish?", description = "Are you looking for golden carp? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.", sourceObjective = "Speak with Ben of the Booming Voice.", sourceObjectiveStatus = "unverified-source-field" }
quests[32685] = { id = 32685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fishing Pole Necessary!", description = "You don't even need to equip a fishing pole in Pandaria!\n\nThe waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!", sourceObjective = "Catch 5 Golden Carp. Try it without a fishing pole!\n\nTo fish, simply click the Fishing icon on the Profession pane. Pay attention to the bobber, click on it when it bobs and you will have your fish!", sourceObjectiveStatus = "unverified-source-field" }
quests[32686] = { id = 32686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Banner of the Mantid Empire", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", sourceObjective = "Put the artifact on display.", progress = "Remove the clutter and put the artifact on display.", completion = "This will aid lorewalkers and archaeologists in understanding the history of Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
