quests[32706] = { id = 32706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", sourceObjective = "Speak to Taran Zhu in Bleak Hollow.", sourceObjectiveStatus = "unverified-source-field" }
quests[32707] = { id = 32707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Isle of Thunder", description = "I do have one thing I would ask of you, {class}.\n\nWe've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals.\n\nIf you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.", sourceObjective = "Recover 3 Shan'ze Ritual Stones. These stones are very rare, and may take some time to gather.", sourceObjectiveStatus = "unverified-source-field" }
quests[32708] = { id = 32708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Trap", description = "Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies.\n\nYou will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants.\n\nWhen your enemy shows itself, show no mercy.", sourceObjective = "Use 3 Shan'ze Ritual Stones to beckon a Champion of the Thunder King, and then kill him.", sourceObjectiveStatus = "unverified-source-field" }
quests[32709] = { id = 32709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", sourceObjective = "Speak to Taran Zhu in Bleak Hollow.", sourceObjectiveStatus = "unverified-source-field" }
quests[32715] = { id = 32715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requiem for a Queen", description = "A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara, the last Queen of the Mogu.\n\nHer sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara's last moments... her brutal murder by the hand of Lei Shen.\n\nSong turns to sadness and Monara weeps, wailing louder and louder into the darkness.", sourceObjective = "Put Monara to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[32718] = { id = 32718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Runes of Fate", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", sourceObjective = "Collect 50 Lesser Charms of Good Fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[32719] = { id = 32719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Runes of Fate", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", sourceObjective = "Collect 50 Lesser Charms of Good Fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[32722] = { id = 32722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead!", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", sourceObjective = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32723] = { id = 32723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse me", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", sourceObjective = "Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32728] = { id = 32728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court of Bones", description = "The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable {class} to see this task through.\n\nGo to him. Aid in whatever ways that you are able.", sourceObjective = "Find Grand Magister Rommath outside the Court of Bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[32729] = { id = 32729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to Halduron when you are best able. He will have work for you.", sourceObjective = "Find Halduron Brightwing outside of Za'Tual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32730] = { id = 32730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihgaluk Crag", description = "Aethas has taken over at Ihgaluk Crag, to the southeast, continuing his effort to turn the Saurok against the Zandalari and mogu.\n\nGo to him, and help in any way that you can.", sourceObjective = "Find Archmage Aethas Sunreaver outside of Ihgaluk Crag.", sourceObjectiveStatus = "unverified-source-field" }
quests[32731] = { id = 32731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court of Bones", description = "The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable {class} to see this task through.\n\nGo to her. Aid in whatever ways that you are able.", sourceObjective = "Find Narasi Snowdawn outside the Court of Bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[32732] = { id = 32732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihgaluk Crag", description = "Archmage Modera has taken over at Ihgaluk Crag, to the southeast, continuing her efforts to turn the Saurok against the Zandalari and mogu.\n\nGo to her, and help in any way that you can.", sourceObjective = "Find Archmage Modera outside of Ihgaluk Crag.", sourceObjectiveStatus = "unverified-source-field" }
quests[32733] = { id = 32733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Archmage Lan'dalock to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to him when you are best able. He will have work for you.", sourceObjective = "Find Archmage Lan'dalock outside of Za'Tual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32836] = { id = 32836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Knockoff Grumplefloot", description = "The \"grumplefloot\" has been hastily carved out of a tree root, with holes unevenly spaced along its length.\n\nA close inspection of its backside, however, reveals words carved into the wood:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return the Knockoff Grumplefloot to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32838] = { id = 32838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Romance and Chivalry", description = "A small book, written for children. It's well-bound and in fairly good condition.\n\nOn the back cover of the book, near the spine, you find a few words written in flowing script:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return The Bear and the Lady Fair to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32840] = { id = 32840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Boom's Fuse", description = "Amidst the gibbets of hozen meat and fur flying aimlessly around Kota Kon's sphere of destruction, you seem to have grabbed hold of a small fuse.\n\nThe fuse is created entirely from woven, matted hozen tail hair. It has a strong smell.\n\nNear one of the ends of the fuse, however, is a small paper tag, embossed with the words:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return Boom Boom's Fuse to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32842] = { id = 32842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeth Like Swords", description = "The tooth comes to a singular edge, almost as if it were sharpened by stone. It clearly belonged to a ferocious beast.\n\nHandling it gingerly, you notice a few tiny words, expertly carved into the enamel:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return the Impeccably Sharp Tooth to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32844] = { id = 32844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret of the Ooze", description = "The contents of the vial swirl and froth violently, causing the vessel to tremble in your hand. As you look into the container, you think you catch a fleeting image of a living, angry face.\n\nThe vial's stopper fits snugly. Around its edge, some small words have been carved with an expert hand:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return the Vial of Reddish Ooze to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32846] = { id = 32846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modified Chomping Apparatus", description = "You might not have recognized this as a modified chomping apparatus if it didn't have the words \"modified chomping apparatus\" messily painted onto it.\n\nRight beneath the sloppy label, you see a smaller message, written much more neatly in bright red ink:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return the Modified Chomping Apparatus to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
quests[32848] = { id = 32848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost-Tipped Eggshell", description = "A piece of an eggshell, presumably penguin. Its edges are covered with rime, and based on its curvature, this egg was quite large when it was intact.\n\nStrangely, the inside of the eggshell has a message written on it, in jade-green ink:\n\nRETURN TO BRAWLER'S GUILD", sourceObjective = "Return the Frost-Tipped Eggshell to someone within your faction's Brawler's Guild.", sourceObjectiveStatus = "unverified-source-field" }
